(()=>{const redirBtn=document.getElementById('redir'),dodgeBtn=document.getElementById('dodge');const baseAttack=attack,baseUpdate=update,baseDraw=draw;attack=function(){const [e]=near(),before=e?e.h:null;baseAttack();if(e&&before!==null&&e.h<before){e.hitFlash=.18;const dx=e.x-P.x,dy=e.y-P.y,m=Math.hypot(dx,dy)||1;e.x+=dx/m*10;e.y+=dy/m*10}};document.getElementById('atk').onpointerdown=attack;update=function(dt){baseUpdate(dt);for(const e of A)if(e.hitFlash)e.hitFlash=Math.max(0,e.hitFlash-dt);let incoming=A.filter(e=>e.h>0&&(e.tele>0||e.wind>0));let t=incoming.length?Math.min(...incoming.map(e=>e.tele||e.wind)):0;redirBtn.classList.toggle('ready',t>0);dodgeBtn.classList.toggle('ready',t>0&&!fly);redirBtn.classList.toggle('now',t>0&&t<=.25);dodgeBtn.classList.toggle('now',t>0&&t<=.25&&!fly)};draw=function(){baseDraw();X.save();for(const e of A){if(e.h<=0)continue;if(e.hitFlash){X.globalAlpha=Math.min(1,e.hitFlash/.18);X.strokeStyle='#ffffff';X.lineWidth=4;X.beginPath();X.arc(e.x,e.y,21,0,Math.PI*2);X.stroke();X.globalAlpha=1}}const r=A.find(e=>e.t==='RUNNER'&&e.h>0);if(r&&escaping){const gx=W*.5,gy=H*.195,total=Math.max(1,Math.hypot(W*.84-gx,H*.66-gy)),left=Math.hypot(r.x-gx,r.y-gy),pct=Math.max(0,Math.min(1,1-left/total));const w=58,h=5,x=r.x-w/2,y=r.y+30;X.fillStyle='#111';X.fillRect(x,y,w,h);X.fillStyle='#f0b92f';X.fillRect(x,y,w*pct,h);X.strokeStyle='#ffffff88';X.lineWidth=1;X.strokeRect(x,y,w,h);X.fillStyle='#fff';X.font='bold 8px Arial';X.textAlign='center';X.fillText('GETAWAY '+Math.round(pct*100)+'%',r.x,y+14)}X.restore()}})();